/*
 * LoRa Receiver — Board 2
 * Receives packets from the Sender board
 * Displays message content and RSSI/SNR on Serial Monitor
 */

#include <SPI.h>
#include <LoRa.h>

#define SS_PIN   10
#define RST_PIN  9
#define DIO0_PIN 2

void setup() {
  Serial.begin(115200);
  while (!Serial);

  Serial.println("LoRa Receiver Starting...");

  LoRa.setPins(SS_PIN, RST_PIN, DIO0_PIN);

  if (!LoRa.begin(868E6)) {
    Serial.println("LoRa init failed!");
    while (1);
  }

  LoRa.setSpreadingFactor(7);
  LoRa.setSignalBandwidth(125000);
  LoRa.setCodingRate4(5);
  LoRa.setSyncWord(0x12);
  LoRa.enableCrc();

  Serial.println("LoRa Receiver ready — waiting for packets...");
  Serial.println("---");
}

void loop() {
  int packetSize = LoRa.parsePacket();

  if (packetSize) {
    Serial.print("Received packet: ");

    String message = "";
    while (LoRa.available()) {
      message += (char)LoRa.read();
    }
    Serial.println(message);

    int rssi = LoRa.packetRssi();
    float snr = LoRa.packetSnr();

    Serial.print("RSSI: ");
    Serial.print(rssi);
    Serial.println(" dBm");

    Serial.print("SNR: ");
    Serial.print(snr);
    Serial.println(" dB");

    Serial.println("---");
  }
}
